package com.ias.finance;
import org.junit.jupiter.api.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import jakarta.servlet.http.HttpServletRequest;
import java.util.*;
import static com.ias.finance.FeeGroup.*;
import static com.ias.finance.JdbcFeeGroups.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;

class FinanceHttpTest {
 JdbcFeeGroupsTest f;MockMvc mvc;String type="EMPLOYEE";String ruleVersion="PUBLISHED_V1";UUID ticket=UUID.randomUUID(),round=UUID.randomUUID();
 @BeforeEach void setup()throws Exception{f=new JdbcFeeGroupsTest();f.setup();FinanceAccess access=new FinanceAccess(){
  public Principal principal(HttpServletRequest r,boolean w){return new Principal(type.equals("EMPLOYEE")?f.actor:new Actor(1,99),type);}
  public Scope scope(HttpServletRequest r,Principal p,UUID t){return new Scope(f.owner,ticket,round);}
  public PublishedRule rule(HttpServletRequest r){return new PublishedRule(ruleVersion,200000);}
  public Access bind(HttpServletRequest r,Principal p){return new Access(){public void current(Actor a,Identity o,String action){f.authority.current(a,o,action);}public void submission(Actor a,Identity o,Submit c,QuoteDetails d){f.authority.submission(a,o,c,d);}public void approval(Actor a,Identity o,UUID id,ApprovalFact fact){throw new SecurityException();}public void verifiedCost(Actor a,Identity o,CostFact fact){throw new SecurityException();}public void execution(Actor a,Identity o,UUID id){throw new SecurityException();}public void customerConfirmation(Actor a,Identity o,QuoteVersion q){if(a.userId()!=99)throw new SecurityException();}};}
 };mvc=MockMvcBuilders.standaloneSetup(new FinanceController(f.source,access)).addFilters(new FinanceRequestBoundary()).setControllerAdvice(new FinanceErrors()).build();}
 Map<String,Object> quote(UUID op,UUID quote){return Map.of("operationId",op.toString(),"quoteId",quote.toString(),"expectedVersion","0","ticketId",ticket.toString(),"replaces",List.of(),"lines",List.of(Map.of("id",UUID.randomUUID().toString(),"amountCents","250000","kind","LABOR")),"chargesCustomer",true,"pricingDescription","实际当前版本费用报价说明");}
 @Test void persistentQuoteAndCustomerConfirmHaveSafeProjectionAndOriginalReceipt()throws Exception{UUID op=UUID.randomUUID(),quote=UUID.randomUUID();String base="/api/finance/groups/"+f.owner.faultGroupId();mvc.perform(post(base+"/quotes").header("Idempotency-Key",op).contentType("application/json").content(FinanceController.JSON.writeValueAsString(quote(op,quote)))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));assertEquals(0,f.count("finance_approval_request"));type="CUSTOMER";var read=mvc.perform(get(base+"/quotes/"+quote)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();assertFalse(read.contains("internalBasis")||read.contains("costFacts")||read.contains("highestApproved"));UUID confirm=UUID.randomUUID();mvc.perform(post(base+"/quotes/"+quote+"/confirm").header("Idempotency-Key",confirm).contentType("application/json").content(FinanceController.JSON.writeValueAsString(Map.of("operationId",confirm.toString(),"expectedVersion","1","quoteVersion","1")))).andExpect(status().isOk());assertEquals(1,f.count("finance_approval_request"));long count=f.count("finance_operation");mvc.perform(get(base+"/operations/"+confirm)).andExpect(status().isOk());assertEquals(count,f.count("finance_operation"));}
 @Test void unknownDuplicateFieldsAndNumericVersionAreRejectedBeforeWrites()throws Exception{String url="/api/finance/groups/"+f.owner.faultGroupId()+"/quotes";UUID op=UUID.randomUUID();var data=new HashMap<>(quote(op,UUID.randomUUID()));data.put("approved",true);mvc.perform(post(url).header("Idempotency-Key",op).contentType("application/json").content(FinanceController.JSON.writeValueAsString(data))).andExpect(status().isBadRequest());data.remove("approved");data.put("expectedVersion",0);mvc.perform(post(url).header("Idempotency-Key",op).contentType("application/json").content(FinanceController.JSON.writeValueAsString(data))).andExpect(status().isBadRequest());mvc.perform(post("/api/finance/tickets/"+ticket+"/group").header("Idempotency-Key",op).contentType("application/json").content("{\"operationId\":\""+op+"\",\"operationId\":\""+op+"\"}")).andExpect(status().isBadRequest());assertEquals(0,f.count("finance_quote_version"));}
 @Test void missingTrustedRuntimeNeverFallsBackToSuppliedIdentity(){var access=new TrustedFinanceAccess();var r=new org.springframework.mock.web.MockHttpServletRequest();r.addHeader("Cookie","IAS-SESSION-DEV=synthetic_finance_session");r.addHeader("X-User-Id","10");var failure=assertThrows(com.ias.trust.Problem.class,()->access.principal(r,false));assertEquals(503,failure.status);}
 @Test void actualUtf8ByteLimitRejectsOversizeWithoutBusinessWrites()throws Exception{UUID op=UUID.randomUUID();mvc.perform(post("/api/finance/tickets/"+ticket+"/group").header("Idempotency-Key",op).contentType("application/json").content("中".repeat(22000))).andExpect(status().isPayloadTooLarge()).andExpect(header().string("Cache-Control","no-store"));assertEquals(1,f.count("finance_operation"));}
 @Test void originalQuoteReusesFrozenRuleAfterNewPublication()throws Exception{UUID op=UUID.randomUUID(),quote=UUID.randomUUID();String url="/api/finance/groups/"+f.owner.faultGroupId()+"/quotes";var command=quote(op,quote);String raw=FinanceController.JSON.writeValueAsString(command);mvc.perform(post(url).header("Idempotency-Key",op).contentType("application/json").content(raw)).andExpect(status().isOk()).andExpect(jsonPath("$.groupVersion").value("1"));ruleVersion="PUBLISHED_V2";mvc.perform(post(url).header("Idempotency-Key",op).contentType("application/json").content(raw)).andExpect(status().isOk()).andExpect(jsonPath("$.groupVersion").value("1"));assertEquals(1,f.count("finance_quote_version"));assertEquals("PUBLISHED_V1",new JdbcQuoteSources(f.source,f.authority).read(f.actor,f.owner,op).command().rule().version());var changed=new HashMap<>(command);changed.put("pricingDescription","不能借规则升级修改原UUID的原报价内容");mvc.perform(post(url).header("Idempotency-Key",op).contentType("application/json").content(FinanceController.JSON.writeValueAsString(changed))).andExpect(status().isConflict());}}
